4	+++ b/src/shapes/Text/f2p_additions.spec.ts
5	@@ -0,0 +1,253 @@
6	+import { describe, expect, it } from 'vitest';
7	+import { FabricText } from './Text';
8	+
9	+/**
10	+ * Behavioural probes for the configurable decoration line-weight feature.
11	+ *
12	+ * These tests deliberately assume NOTHING about:
13	+ *   - what the new public property is called,
14	+ *   - what CSS declaration / SVG attribute carries it,
15	+ *   - what unit or numeric scale it is expressed in,
16	+ *   - whether it is emitted as `name: value` or `name="value"`.
17	+ *
18	+ * The control is *discovered* at runtime: we look for a serialisable numeric
19	+ * property that, when scaled, makes some numeric value in the emitted SVG
20	+ * scale by the same factor. Any behaviourally correct implementation is found
21	+ * by that probe; an unfixed library is not.
22	+ */
23	+
24	+/** Numeric properties an unfixed text object already serialises. */
25	+const PRE_EXISTING_NUMERIC_PROPS = [
26	+  'left',
27	+  'top',
28	+  'width',
29	+  'height',
30	+  'scaleX',
31	+  'scaleY',
32	+  'angle',
33	+  'opacity',
34	+  'strokeWidth',
35	+  'strokeMiterLimit',
36	+  'strokeDashOffset',
37	+  'skewX',
38	+  'skewY',
39	+  'fontSize',
40	+  'fontWeight',
41	+  'lineHeight',
42	+  'charSpacing',
43	+  'deltaY',
44	+  'pathStartOffset',
45	+  'padding',
46	+  'minScaleLimit',
47	+  'cornerSize',
48	+  'touchCornerSize',
49	+  'borderScaleFactor',
50	+  'rotatingPointOffset',
51	+  'borderOpacityWhenMoving',
52	+  'CACHE_FONT_SIZE',
53	+  'MIN_TEXT_WIDTH',
54	+];
55	+
56	+const LOW = 100;
57	+const HIGH = 300;
58	+const RATIO = HIGH / LOW;
59	+
60	+/**
61	+ * Every `name: 12.5` CSS declaration and every `name="12.5"` XML attribute in
62	+ * the SVG, collected as { declarationName: [numbers, in document order] }.
63	+ * Trailing units (%, px, em, ...) are ignored, so the unit is never pinned.
64	+ */
65	+function numericDeclarations(svg) {
66	+  const out = Object.create(null);
67	+  const push = (name, raw) => {
68	+    const value = parseFloat(raw);
69	+    if (!isFinite(value)) {
70	+      return;
71	+    }
72	+    if (!out[name]) {
73	+      out[name] = [];
74	+    }
75	+    out[name].push(value);
76	+  };
77	+
78	+  const cssRe = /([a-zA-Z][\w-]*)\s*:\s*(-?\d*\.?\d+)/g;
79	+  let m;
80	+  while ((m = cssRe.exec(svg)) !== null) {
81	+    push(m[1], m[2]);
82	+  }
83	+
84	+  const attrRe = /([a-zA-Z][\w-]*)\s*=\s*"(-?\d*\.?\d+)[^"]*"/g;
85	+  while ((m = attrRe.exec(svg)) !== null) {
86	+    push(m[1], m[2]);
87	+  }
88	+
89	+  return out;
90	+}
91	+
92	+/** Numeric properties on a text object that the unfixed library did not have. */
93	+function candidateProps() {
94	+  const serialized = new FabricText('X', { underline: true }).toObject();
95	+  return Object.keys(serialized).filter(
96	+    (key) =>
97	+      typeof serialized[key] === 'number' &&
98	+      key.charAt(0) !== '_' &&
99	+      PRE_EXISTING_NUMERIC_PROPS.indexOf(key) === -1,
100	+  );
101	+}
102	+
103	+function closeEnough(actual, expected) {
104	+  return Math.abs(actual - expected) <= Math.max(0.02, Math.abs(expected) * 0.02);
105	+}
106	+
107	+/**
108	+ * Find { prop, decl }: a public property `prop` whose value is reported in the
109	+ * emitted SVG through declaration `decl`, proportionally.
110	+ * Returns null when no such control exists (i.e. on an unfixed library).
111	+ */
112	+function discoverKnob() {
113	+  const props = candidateProps();
114	+  for (let p = 0; p < props.length; p++) {
115	+    const prop = props[p];
116	+    const lowSvg = new FabricText('X', {
117	+      underline: true,
118	+      [prop]: LOW,
119	+    }).toSVG();
120	+    const highSvg = new FabricText('X', {
121	+      underline: true,
122	+      [prop]: HIGH,
123	+    }).toSVG();
124	+    if (lowSvg === highSvg) {
125	+      continue;
126	+    }
127	+    const low = numericDeclarations(lowSvg);
128	+    const high = numericDeclarations(highSvg);
129	+    const names = Object.keys(low);
130	+    for (let n = 0; n < names.length; n++) {
131	+      const decl = names[n];
132	+      const lowVals = low[decl];
133	+      const highVals = high[decl];
134	+      if (!highVals || highVals.length !== lowVals.length) {
135	+        continue;
136	+      }
137	+      let scales = false;
138	+      let consistent = true;
139	+      for (let i = 0; i < lowVals.length; i++) {
140	+        const l = lowVals[i];
141	+        const h = highVals[i];
142	+        if (l !== 0 && closeEnough(h, l * RATIO)) {
143	+          scales = true;
144	+        } else if (l !== h) {
145	+          consistent = false;
146	+          break;
147	+        }
148	+      }
149	+      if (scales && consistent) {
150	+        return { prop: prop, decl: decl };
151	+      }
152	+    }
153	+  }
154	+  return null;
155	+}
156	+
157	+function valuesOf(svg, decl) {
158	+  return numericDeclarations(svg)[decl] || [];
159	+}
160	+
161	+function distinctCount(values) {
162	+  const seen = {};
163	+  let n = 0;
164	+  for (let i = 0; i < values.length; i++) {
165	+    const k = String(values[i]);
166	+    if (!seen[k]) {
167	+      seen[k] = true;
168	+      n++;
169	+    }
170	+  }
171	+  return n;
172	+}
173	+
174	+describe('text decoration line weight', () => {
175	+  it('decoration weight is configurable and scales the emitted SVG', () => {
176	+    const knob = discoverKnob();
177	+    expect(
178	+      knob,
179	+      'no public property makes the decoration weight in the emitted SVG scale with it',
180	+    ).not.toBeNull();
181	+  });
182	+
183	+  it('decoration weight applies to underline, overline and linethrough', () => {
184	+    const knob = discoverKnob();
185	+    expect(knob).not.toBeNull();
186	+
187	+    const text = new FabricText('abc', {
188	+      styles: {
189	+        0: {
190	+          0: { underline: true, [knob.prop]: 40 },
191	+          1: { overline: true, [knob.prop]: 160 },
192	+          2: { linethrough: true, [knob.prop]: 280 },
193	+        },
194	+      },
195	+    });
196	+
197	+    // One distinct reported weight per decoration type.
198	+    expect(distinctCount(valuesOf(text.toSVG(), knob.decl))).toBeGreaterThanOrEqual(3);
199	+  });
200	+
201	+  it('decoration weight varies per character inside one text object', () => {
202	+    const knob = discoverKnob();
203	+    expect(knob).not.toBeNull();
204	+
205	+    const text = new FabricText('AB', {
206	+      underline: true,
207	+      styles: {
208	+        0: {
209	+          0: { [knob.prop]: 50 },
210	+          1: { [knob.prop]: 400 },
211	+        },
212	+      },
213	+    });
214	+
215	+    const values = valuesOf(text.toSVG(), knob.decl);
216	+    expect(values.length).toBeGreaterThanOrEqual(2);
217	+    expect(distinctCount(values)).toBeGreaterThanOrEqual(2);
218	+  });
219	+
220	+  it('decoration weight survives object round-trip serialization', async () => {
221	+    const knob = discoverKnob();
222	+    expect(knob).not.toBeNull();
223	+
224	+    const original = new FabricText('AB', {
225	+      underline: true,
226	+      [knob.prop]: 220,
227	+      styles: {
228	+        0: {
229	+          1: { [knob.prop]: 40 },
230	+        },
231	+      },
232	+    });
233	+
234	+    const restored = await FabricText.fromObject(original.toObject());
235	+    expect(restored.toSVG()).toBe(original.toSVG());
236	+  });
237	+
238	+  it('default decoration weight is exposed and left unchanged', () => {
239	+    const knob = discoverKnob();
240	+    expect(knob).not.toBeNull();
241	+
242	+    const stock = new FabricText('X', { underline: true });
243	+    const stockSvg = stock.toSVG();
244	+
245	+    const values = valuesOf(stockSvg, knob.decl);
246	+    expect(values.length).toBeGreaterThanOrEqual(1);
247	+    expect(values.every((v) => v > 0)).toBe(true);
248	+
249	+    // Opting in with the serialised default must be a no-op for existing users.
250	+    const defaultValue = stock.toObject()[knob.prop];
251	+    expect(typeof defaultValue).toBe('number');
252	+    const explicit = new FabricText('X', {
253	+      underline: true,
254	+      [knob.prop]: defaultValue,
255	+    });
256	+    expect(explicit.toSVG()).toBe(stockSvg);
257	+  });
258	+});
