[
  {
    "role": "design_ref",
    "url": "https://github.com/user-attachments/assets/e7d4eb10-acba-40ae-a709-5c20be416ecc",
    "local_path": "/app/.harbor_assets/design_ref_1.png",
    "description": "Target behaviour, rendered by the reference browser engine: three lines of text whose underlines carry visibly different weights (thin, heavy, and the shorthand form), with the weight changing mid-line from one run of characters to the next."
  },
  {
    "role": "design_ref",
    "url": "https://github.com/user-attachments/assets/b9f9ee57-5e76-4916-a0ab-d9bb95f9d6aa",
    "local_path": "/app/.harbor_assets/design_ref_2.png",
    "description": "The same exported markup in a second browser engine: the weights are honoured but the heavy segments are drawn detached and offset above the baseline. This cross-renderer inconsistency is an accepted trade-off, not a defect to correct."
  },
  {
    "role": "design_ref",
    "url": "https://github.com/user-attachments/assets/5fdeb733-e3ed-4f83-b875-e95e54eb03eb",
    "local_path": "/app/.harbor_assets/design_ref_3.png",
    "description": "The same exported markup in a third browser engine: weights honoured, decoration lines positioned slightly lower than the reference. Also an accepted trade-off."
  },
  {
    "role": "design_ref",
    "url": "https://github.com/user-attachments/assets/9e3fef60-e0c7-4936-a69d-4c719cf3cc80",
    "local_path": "/app/.harbor_assets/design_ref_4.png",
    "description": "The same exported markup in a fourth browser engine, which drops some of the weighted decorations entirely. Accepted renderer limitation — the library's job is to emit the weight, not to compensate for consumers of the markup."
  },
  {
    "role": "design_ref",
    "url": "https://github.com/user-attachments/assets/3e65553c-c26b-4e52-8c46-c253740ef54e",
    "local_path": "/app/.harbor_assets/design_ref_5.png",
    "description": "Target canvas render: a single text object carrying all three decoration kinds at once — line above, line through and line below — where each run of characters sets its own decoration weight independently (thin blue runs next to heavy green runs)."
  },
  {
    "role": "design_ref",
    "url": "https://github.com/user-attachments/assets/331df990-fd0d-47a2-847a-a4f4368c1cd8",
    "local_path": "/app/.harbor_assets/design_ref_6.png",
    "description": "Target canvas render with the selection box visible: two lines of text where per-character decoration weight varies across all three decoration kinds. Note the heaviest decorations extending past the object's bounding box — the accepted visual trade-off of the feature."
  }
]

